/* ═══════════════════════════════════════════════════════════
   🟢 仿微信 WeChat Theme — 日夜自动切换版 v5.1
   利用 data-time-of-day 属性自动跟随系统时间
   morning + day = 日间模式 | evening + night = 夜间模式
   ✅ 头像大小 & 气泡字体 跟随系统滑块自适应
   by 자기야
   ═══════════════════════════════════════════════════════════ */

/* ╔═══════════════════════════════════════╗
   ║  第一部分：日间变量（morning + day）  ║
   ╚═══════════════════════════════════════╝ */
.chat-detail-screen[data-time-of-day="morning"],
.chat-detail-screen[data-time-of-day="day"] {
    --wx-bg: #ededed;
    --wx-header-border: #d5d5d5;
    --wx-title-color: #000;
    --wx-dots-color: #000;
    --wx-icon-invert: none;
    --wx-timestamp-color: #a5a5a5;
    --wx-bubble-them-bg: #ffffff;
    --wx-bubble-them-color: #000;
    --wx-bubble-me-bg: #95ec69;
    --wx-bubble-me-color: #000;
    --wx-input-bg: #f7f7f7;
    --wx-input-border: #d5d5d5;
    --wx-input-box-bg: #ffffff;
    --wx-input-text: #000;
    --wx-status-color: #a5a5a5;
    --wx-quote-bg: #E3E3E3;
    --wx-quote-color: #8a8a8a;
    --wx-transfer-bg: #f5af3c;
    --wx-more-bg: #f7f7f7;
    --wx-more-border: #d5d5d5;
    --wx-more-text: #000;
    --wx-more-shadow: rgba(0,0,0,0.15);
    --wx-scrollbar: rgba(0,0,0,0.15);
    --wx-selection-bg: rgba(7,193,96,0.25);
    --wx-selection-color: #000;
    --wx-translation-hint: #b2b2b2;
    --wx-voice-duration-color: #1A1A1A;
    --wx-voice-card-text-color: #1A1A1A;
    --wx-videocall-time-color: #000;
}

/* ╔═══════════════════════════════════════╗
   ║  第二部分：夜间变量（evening + night） ║
   ╚═══════════════════════════════════════╝ */
.chat-detail-screen[data-time-of-day="evening"],
.chat-detail-screen[data-time-of-day="night"] {
    --wx-bg: #1a1a1a;
    --wx-header-border: #2a2a2a;
    --wx-title-color: #ffffff;
    --wx-dots-color: #ffffff;
    --wx-icon-invert: brightness(0) invert(1);
    --wx-timestamp-color: #777;
    --wx-bubble-them-bg: #2c2c2c;
    --wx-bubble-them-color: #e5e5e5;
    --wx-bubble-me-bg: #27AE60;
    --wx-bubble-me-color: #000;
    --wx-input-bg: #262626;
    --wx-input-border: #333;
    --wx-input-box-bg: #3a3a3a;
    --wx-input-text: #e5e5e5;
    --wx-status-color: #777;
    --wx-quote-bg: #383838;
    --wx-quote-color: #9a9a9a;
    --wx-transfer-bg: #c87f1e;
    --wx-more-bg: #2c2c2c;
    --wx-more-border: #3a3a3a;
    --wx-more-text: #e5e5e5;
    --wx-more-shadow: rgba(0,0,0,0.3);
    --wx-scrollbar: rgba(255,255,255,0.15);
    --wx-selection-bg: rgba(7,193,96,0.35);
    --wx-selection-color: #fff;
    --wx-translation-hint: #666;
    --wx-voice-duration-color: #e5e5e5;
    --wx-voice-card-text-color: #e5e5e5;
    --wx-videocall-time-color: #e5e5e5;
}

/* ╔═══════════════════════════════════════╗
   ║  第三部分：公共固定变量               ║
   ╚═══════════════════════════════════════╝ */
.chat-detail-screen {
    --wx-edge-padding: -2px;
    --wx-time-gap: 16px;
    --translation-always-show: 0;
    --wx-input-width: 238px;
    --wx-avatar-radius: 3px;

    /* 转账卡片变量 */
    --tc-me-pending-width: 210px;
    --tc-me-pending-height: 75px;
    --tc-me-pending-offset-x: 4px;
    --tc-me-pending-offset-y: 0px;
    --tc-me-pending-left: 54px;
    --tc-me-pending-top: 10px;

    --tc-me-accepted-width: 210px;
    --tc-me-accepted-height: 75px;
    --tc-me-accepted-offset-x: 4px;
    --tc-me-accepted-offset-y: 0px;
    --tc-me-accepted-left: 50px;
    --tc-me-accepted-top: 8px;

    --tc-me-refunded-width: 210px;
    --tc-me-refunded-height: 75px;
    --tc-me-refunded-offset-x: 4px;
    --tc-me-refunded-offset-y: 0px;
    --tc-me-refunded-left: 50px;
    --tc-me-refunded-top: 10px;

    --tc-them-pending-width: 210px;
    --tc-them-pending-height: 75px;
    --tc-them-pending-offset-x: -3px;
    --tc-them-pending-offset-y: 0px;
    --tc-them-pending-left: 58px;
    --tc-them-pending-top: 10px;

    --tc-them-accepted-width: 210px;
    --tc-them-accepted-height: 70px;
    --tc-them-accepted-offset-x: -3px;
    --tc-them-accepted-offset-y: 0px;
    --tc-them-accepted-left: 56px;
    --tc-them-accepted-top: 8px;

    --tc-them-refunded-width: 210px;
    --tc-them-refunded-height: 75px;
    --tc-them-refunded-offset-x: -3px;
    --tc-them-refunded-offset-y: 0px;
    --tc-them-refunded-left: 54px;
    --tc-them-refunded-top: 10px;

    /* 语音相关 */
    --wx-voice-card-gap: -3px;
    --wx-voice-card-offset-x: 6px;
    --voice-me-offset-x: 62px;
    --voice-me-offset-y: 2px;
    --wx-voice-card-gap-me: -1px;
    --wx-voice-card-offset-x-me: 44px;
    --voice-me-duration-left: 40px;
    --voice-me-duration-top: 25%;
    --voice-me-width: auto;
    --voice-me-height: 32px;
    --wx-transfer-card-gap: -3px;
    --wx-voice-card-max-subtract: 65px;

    /* 独立引用条配置 */
    --reply-detached-min-height: auto;
    --reply-detached-padding: 4px 8px;
    --reply-detached-margin-top: 4px;
    --reply-detached-margin-bottom: 0px;
    --reply-detached-offset-x: -4px;
    --reply-detached-offset-x-them: 5px;
    --reply-detached-flex-direction: row;
    --reply-detached-align-items: baseline;
    --reply-detached-gap: 6px;
    --reply-detached-text-whitespace: normal;

    /* 礼物卡片配置 */
    --gift-card-width: 213px;
    --gift-card-height: 85px;
    --gift-card-radius: 8px;
    --gift-card-gap: 0px;
    --gift-card-offset-y: -3px;
    --gift-card-img-pending: url("https://i.postimg.cc/BZDBbbmT/li-wu-wei-xin-dui-fang-20.png");
    --gift-card-img-accepted: url("https://i.postimg.cc/HsmvCRQn/li-wu-yi-jie-shou-dui-fang-21.png");

    --gift-ribbon-color: transparent;
    --gift-ribbon-dark: transparent;
    --gift-shadow-color: transparent;
    --gift-me-ribbon-color: transparent;
    --gift-me-ribbon-dark: transparent;
    --gift-me-box-light: transparent;
    --gift-me-label-color: transparent;
    --gift-them-ribbon-color: transparent;
    --gift-them-ribbon-dark: transparent;
    --gift-them-label-color: transparent;

    --gift-me-card-width: 213px;
    --gift-me-card-height: 85px;
    --gift-me-card-offset-x: 2px;
    --gift-me-card-offset-y: -3px;
    --gift-me-card-img-pending: url("https://i.postimg.cc/FFGGHTy8/song-ni-yi-fen-xin-yi-wo-fang-20.png");
    --gift-me-card-img-accepted: url("https://i.postimg.cc/9FnpGzNx/dui-fang-yi-shou-xia-le-li-wu-21.png");

    /* 独立翻译条配置 */
    --trans-gap: 4px;
    --trans-padding-x: 9px;
    --trans-padding-y: 7px;
    --trans-radius: 4px;
    --trans-font-size: 14px;
    --trans-line-height: 1.45;
    --trans-offset-x-them: 5px;
    --trans-offset-x-me: -5px;
    --trans-hint-display: block;

    /* 视频通话卡片 */
    --videocall-them-offset-x: -10px;
    --videocall-them-offset-y: -2px;
    --videocall-them-width: 160px;
    --videocall-them-height: 40px;
    --videocall-them-time-size: 17px;
    --videocall-them-time-left: 62%;
    --videocall-them-time-top: 50%;
    --videocall-them-missed-offset-x: -15px;
    --videocall-them-missed-offset-y: -2px;
    --videocall-them-missed-width: 120px;
    --videocall-them-missed-height: 40px;
    --videocall-me-offset-x: 8px;
    --videocall-me-offset-y: -2px;
    --videocall-me-width: 160px;
    --videocall-me-height: 40px;
    --videocall-me-time-size: 17px;
    --videocall-me-time-left: 50%;
    --videocall-me-time-top: 50%;
    --videocall-me-missed-offset-x: 8px;
    --videocall-me-missed-offset-y: -2px;
    --videocall-me-missed-width: 150px;
    --videocall-me-missed-height: 38px;
}

/* 地图定位卡片 — 日间 */
.chat-detail-screen[data-time-of-day="morning"],
.chat-detail-screen[data-time-of-day="day"] {
    --loc-them-img: url("https://i.postimg.cc/q7pkY4LW/de-tu-tao-ke-dui-fang-22.png");
    --loc-them-text-color: #000;
    --loc-them-addr-color: #999;
    --loc-me-img: url("https://i.postimg.cc/90gRXzx9/wei-xin-ding-wei-de-tu-tao-ke-22.png");
    --loc-me-text-color: #000;
    --loc-me-addr-color: #999;
}
/* 地图定位卡片 — 夜间 */
.chat-detail-screen[data-time-of-day="evening"],
.chat-detail-screen[data-time-of-day="night"] {
    --loc-them-img: url("https://i.postimg.cc/Z53pyGKN/dui-fang-de-tu-22.png");
    --loc-them-text-color: #e5e5e5;
    --loc-them-addr-color: #777;
    --loc-me-img: url("https://i.postimg.cc/HsMVSQG2/wo-fang-de-tu-22.png");
    --loc-me-text-color: #e5e5e5;
    --loc-me-addr-color: #777;
}
/* 地图定位公共尺寸 */
.chat-detail-screen {
    --loc-them-width: 240px;
    --loc-them-height: 150px;
    --loc-them-radius: 4px;
    --loc-them-gap: -4px;
    --loc-them-offset-y: -5px;
    --loc-them-text-left: 15px;
    --loc-them-text-top: 10px;
    --loc-them-title-size: 15px;
    --loc-them-title-weight: 300;
    --loc-them-addr-size: 11px;
    --loc-them-addr-weight: 400;
    --loc-me-width: 240px;
    --loc-me-height: 150px;
    --loc-me-radius: 4px;
    --loc-me-gap: 8px;
    --loc-me-offset-y: -8px;
    --loc-me-text-left: 15px;
    --loc-me-text-top: 12px;
    --loc-me-title-size: 15px;
    --loc-me-title-weight: 300;
    --loc-me-addr-size: 11px;
    --loc-me-addr-weight: 400;
}

/* ================================================
 * 聊天背景
 * ================================================ */
.chat-detail-screen {
    background-color: var(--wx-bg) !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
}

.chat-messages-area {
    padding: 8px 0 !important;
    position: relative !important;
}
.chat-messages-area::before {
    content: "" !important;
    position: fixed !important;
    top: 0; left: 0; right: 0; bottom: 0 !important;
    background: var(--wx-bg) !important;
    z-index: 0 !important;
    pointer-events: none !important;
}
.chat-messages-area > * {
    position: relative !important;
    z-index: 1 !important;
}
.chat-message-list-custom {
    background-color: transparent !important;
    padding-bottom: 4px !important;
}

/* ================================================
 * 顶栏（自适配所有机型）
 * ================================================ */
.chat-header-custom {
    background: var(--wx-bg) !important;
    background-image: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border-bottom: 0.5px solid var(--wx-header-border) !important;
    border-radius: 0 !important;
    padding: 0 !important;
    padding-top: env(safe-area-inset-top, 0px) !important;
    height: calc(44px + env(safe-area-inset-top, 0px)) !important;
    min-height: calc(44px + env(safe-area-inset-top, 0px)) !important;
    max-height: calc(44px + env(safe-area-inset-top, 0px)) !important;
    margin: 0 !important;
    position: relative !important;
    box-shadow: none !important;
    width: 100% !important;
    display: block !important;
    overflow: visible !important;
    z-index: 999 !important;
    isolation: isolate !important;
}

.chat-header-custom::before {
    content: "" !important;
    position: absolute !important;
    top: 0; left: 0; right: 0; bottom: 0 !important;
    background: var(--wx-bg) !important;
    z-index: 0 !important;
    pointer-events: none !important;
}

.chat-header-content {
    position: relative !important;
    width: 100% !important;
    height: 52px !important;
    padding: 0 !important;
    margin: 0 !important;
    min-height: 52px !important;
    display: block !important;
    z-index: 1 !important;
}

.header-left-section,
.header-actions,
.header-btn-back-wrapper,
.header-avatar-container,
.chat-header-avatar,
.chat-header-subtitle {
    display: none !important;
    visibility: hidden !important;
    width: 0 !important;
    height: 0 !important;
}

.header-profile-section,
.header-title-container {
    position: absolute !important;
    left: 50% !important;
    top: 40px !important;
    bottom: 0 !important;
    transform: translateX(-50%) !important;
    width: auto !important;
    max-width: calc(100vw - 200px) !important;
    height: 52px !important;
    margin: 0 !important;
    padding: 0 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    background: transparent !important;
    overflow: hidden !important;
    z-index: 5 !important;
}

.chat-header-title {
    position: static !important;
    display: block !important;
    color: var(--wx-title-color) !important;
    font-size: 15px !important;
    font-weight: 600 !important;
    text-align: center !important;
    line-height: 52px !important;
    height: 52px !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    background: transparent !important;
    transform: none !important;
}
.chat-header-title::before,
.chat-header-title::after {
    display: none !important;
    content: none !important;
}

.header-btn-back {
    position: absolute !important;
    top: 11px; left: 10px !important;
    width: 32px !important;
    height: 32px !important;
    margin: 0 !important;
    padding: 0 !important;
    background: transparent !important;
    border: none !important;
    cursor: pointer !important;
    z-index: 100 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    color: transparent !important;
    -webkit-text-fill-color: transparent !important;
    font-size: 0 !important;
}
.header-btn-back::before,
.header-btn-back::after {
    display: none !important;
    content: none !important;
}
.header-btn-back svg {
    display: block !important;
    width: 22px !important;
    height: 22px !important;
    color: var(--wx-title-color) !important;
    stroke: var(--wx-title-color) !important;
    fill: none !important;
    filter: var(--wx-icon-invert) !important;
}

.header-btn-info {
    position: absolute !important;
    top: -20px; right: 10px !important;
    width: 30px !important;
    height: 30px !important;
    margin: 0 !important;
    padding: 0 !important;
    background: transparent !important;
    background-image: none !important;
    border: none !important;
    cursor: pointer !important;
    z-index: 100 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
}
.header-btn-info::before {
    content: '' !important;
    display: block !important;
    width: 4px; height: 4px !important;
    border-radius: 50% !important;
    background: var(--wx-dots-color) !important;
    box-shadow: -8px 0 0 var(--wx-dots-color), 8px 0 0 var(--wx-dots-color) !important;
}
.header-btn-info svg,
.header-btn-info > svg,
.header-btn-info img {
    display: none !important;
}
.header-btn-info::after {
    display: none !important;
    content: none !important;
}

.header-btn-video {
    display: block !important;
    position: absolute !important;
    top: -20px; right: 50px !important;
    width: 30px; height: 30px !important;
    background: transparent !important;
    background-image: none !important;
    border: none !important;
    cursor: pointer !important;
    z-index: 100 !important;
    opacity: 0 !important;
    pointer-events: auto !important;
}
.header-btn-video svg, .header-btn-video * { display: none !important; }

.header-btn-phone {
    display: block !important;
    position: absolute !important;
    top: -20px; right: 90px !important;
    width: 30px; height: 30px !important;
    background: transparent !important;
    background-image: none !important;
    border: none !important;
    cursor: pointer !important;
    z-index: 100 !important;
    opacity: 0 !important;
    pointer-events: auto !important;
}
.header-btn-phone svg, .header-btn-phone * { display: none !important; }

/* ================================================
 * 时间戳
 * ================================================ */
.timestamp-custom,
.date-divider-custom {
    color: var(--wx-timestamp-color) !important;
    font-size: 11px !important;
    font-weight: 400 !important;
    background: transparent !important;
    text-align: center !important;
    margin: var(--wx-time-gap) auto !important;
    padding: 0 !important;
    display: block !important;
    box-shadow: none !important;
    border: none !important;
}

/* ================================================
 * 消息行布局
 * ================================================ */
.msg-bubble-wrapper {
    display: flex !important;
    flex-direction: row !important;
    align-items: flex-start !important;
    width: 100% !important;
    padding-left: var(--wx-edge-padding) !important;
    padding-right: var(--wx-edge-padding) !important;
    margin: 5px 0 !important;
    box-sizing: border-box !important;
    gap: 0 !important;
}
.msg-bubble-wrapper.msg-me { justify-content: flex-end !important; }
.msg-bubble-wrapper.msg-them { justify-content: flex-start !important; }

/* ================================================
 * 头像 — 不锁定宽高，让App系统滑块自由控制
 * 只设置外观（圆角、间距、布局顺序）
 * ================================================ */
.msg-avatar-them-container,
.msg-bubble-wrapper.msg-them .msg-avatar-them-container {
    margin: 0 6px 0 0 !important;
    padding: 0 !important;
    border-radius: var(--wx-avatar-radius) !important;
    overflow: hidden !important;
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
    transform: none !important;
    display: block !important;
    align-self: flex-start !important;
    order: 1 !important;
    position: relative !important;
    z-index: 2 !important;
}
.msg-avatar-them-inner {
    border-radius: var(--wx-avatar-radius) !important;
    overflow: hidden !important;
}
.msg-avatar-them-container img,
.msg-avatar-them-inner img,
.msg-avatar-custom {
    border-radius: var(--wx-avatar-radius) !important;
    object-fit: cover !important;
    display: block !important;
}

.msg-avatar-me-container,
.msg-bubble-wrapper.msg-me .msg-avatar-me-container {
    margin: 0 0 0 6px !important;
    padding: 0 !important;
    border-radius: var(--wx-avatar-radius) !important;
    overflow: hidden !important;
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
    transform: none !important;
    display: block !important;
    align-self: flex-start !important;
    order: 3 !important;
    position: relative !important;
    z-index: 2 !important;
}
.msg-avatar-me-inner {
    border-radius: var(--wx-avatar-radius) !important;
    overflow: hidden !important;
}
.msg-avatar-me-container img,
.msg-avatar-me-inner img {
    border-radius: var(--wx-avatar-radius) !important;
    object-fit: cover !important;
    display: block !important;
}

/* ================================================
 * 内容栈
 * ================================================ */
.msg-content-stack {
    flex: 0 1 auto !important;
    max-width: calc(100vw - 120px) !important;
    min-width: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    order: 2 !important;
    display: flex !important;
    flex-direction: column !important;
    z-index: 1 !important;
}
.msg-me .msg-content-stack { align-items: flex-end !important; }
.msg-them .msg-content-stack { align-items: flex-start !important; }

/* ================================================
 * 气泡 — 不设font-size，让App系统滑块自由控制字体
 * 只设置外观（背景色、圆角、间距、换行）
 * ================================================ */
.bubble-them-custom {
    position: relative !important;
    background: var(--wx-bubble-them-bg) !important;
    color: var(--wx-bubble-them-color) !important;
    border-radius: 4px !important;
    padding: 8px 9px !important;
    margin: 0 0 0 5px !important;
    max-width: 100% !important;
    width: auto !important;
    line-height: 1.45 !important;
    word-break: break-word !important;
    overflow-wrap: break-word !important;
    white-space: normal !important;
    border: none !important;
    box-shadow: none !important;
    display: inline-block !important;
    box-sizing: border-box !important;
}
.bubble-them-custom:not(:has([class*="couples"])) *,
.bubble-them-custom:not(:has([class*="couples"])) p,
