}

.header-btn-info {
    position: absolute !important;
    top: -20px; right: 10px !important;
    width: 30px !important;
    height: 30px !important;
    margin: 0 !important;
    padding: 0 !important;
    background: transparent !important;
    background-image: none !important;
    border: none !important;
