    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
    transform: none !important;
    display: block !important;
    align-self: flex-start !important;
    order: 1 !important;
    position: relative !important;
    z-index: 2 !important;
}
.msg-avatar-them-inner {
    border-radius: var(--wx-avatar-radius) !important;
    overflow: hidden !important;
}
.msg-avatar-them-container img,
.msg-avatar-them-inner img,
.msg-avatar-custom {
    border-radius: var(--wx-avatar-radius) !important;
    object-fit: cover !important;
    display: block !important;
}

.msg-avatar-me-container,
.msg-bubble-wrapper.msg-me .msg-avatar-me-container {
    margin: 0 0 0 6px !important;
    padding: 0 !important;
    border-radius: var(--wx-avatar-radius) !important;
    overflow: hidden !important;
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
    transform: none !important;
    display: block !important;
    align-self: flex-start !important;
    order: 3 !important;
    position: relative !important;
    z-index: 2 !important;
}
.msg-avatar-me-inner {
    border-radius: var(--wx-avatar-radius) !important;
    overflow: hidden !important;
}
.msg-avatar-me-container img,
.msg-avatar-me-inner img {
    border-radius: var(--wx-avatar-radius) !important;
    object-fit: cover !important;
    display: block !important;
}

/* ================================================
 * 内容栈
 * ================================================ */
.msg-content-stack {
    flex: 0 1 auto !important;
    max-width: calc(100vw - 120px) !important;
    min-width: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    order: 2 !important;
    display: flex !important;
    flex-direction: column !important;
    z-index: 1 !important;
}
.msg-me .msg-content-stack { align-items: flex-end !important; }
.msg-them .msg-content-stack { align-items: flex-start !important; }

/* ================================================
 * 气泡 — 不设font-size，让App系统滑块自由控制字体
 * 只设置外观（背景色、圆角、间距、换行）
 * ================================================ */
.bubble-them-custom {
    position: relative !important;
    background: var(--wx-bubble-them-bg) !important;
    color: var(--wx-bubble-them-color) !important;
    border-radius: 4px !important;
    padding: 8px 9px !important;
    margin: 0 0 0 5px !important;
    max-width: 100% !important;
    width: auto !important;
    line-height: 1.45 !important;
    word-break: break-word !important;
    overflow-wrap: break-word !important;
    white-space: normal !important;
    border: none !important;
    box-shadow: none !important;
    display: inline-block !important;
    box-sizing: border-box !important;
}
.bubble-them-custom:not(:has([class*="couples"])) *,
.bubble-them-custom:not(:has([class*="couples"])) p,
.bubble-them-custom:not(:has([class*="couples"])) span,
.bubble-them-custom:not(:has([class*="couples"])) div {
    line-height: inherit !important;
    color: var(--wx-bubble-them-color) !important;
    -webkit-text-fill-color: var(--wx-bubble-them-color) !important;
}
.bubble-them-custom::before {
    content: '' !important;
    position: absolute !important;
    left: -5px; top: 13px !important;
    border-top: 5px solid transparent !important;
    border-bottom: 5px solid transparent !important;
    border-right: 6px solid var(--wx-bubble-them-bg) !important;
    background: none !important;
    pointer-events: none !important;
}
.bubble-them-custom::after { display: none !important; }

.bubble-me-custom {
    position: relative !important;
    background: var(--wx-bubble-me-bg) !important;
    color: var(--wx-bubble-me-color) !important;
    border-radius: 4px !important;
    padding: 8px 9px !important;
    margin: 0 5px 0 0 !important;
    max-width: 100% !important;
    width: auto !important;
    line-height: 1.45 !important;
    word-break: break-word !important;
    overflow-wrap: break-word !important;
    white-space: normal !important;
    border: none !important;
    box-shadow: none !important;
    display: inline-block !important;
    box-sizing: border-box !important;
}
.bubble-me-custom:not(:has([class*="couples"])) *,
.bubble-me-custom:not(:has([class*="couples"])) p,
.bubble-me-custom:not(:has([class*="couples"])) span,
.bubble-me-custom:not(:has([class*="couples"])) div {
    line-height: inherit !important;
    color: var(--wx-bubble-me-color) !important;
    -webkit-text-fill-color: var(--wx-bubble-me-color) !important;
}
.bubble-me-custom::before {
    content: '' !important;
    position: absolute !important;
    right: -5px; top: 13px !important;
    border-top: 5px solid transparent !important;
    border-bottom: 5px solid transparent !important;
    border-left: 6px solid var(--wx-bubble-me-bg) !important;
    background: none !important;
    pointer-events: none !important;
}
.bubble-me-custom::after { display: none !important; }

/* ================================================
 * 图片/视频/特殊卡片：去气泡背景和三角
 * ================================================ */
.bubble-them-custom:has(img),
.bubble-me-custom:has(img),
.bubble-them-custom:has(.msg-image-wrapper),
.bubble-me-custom:has(.msg-image-wrapper),
.bubble-them-custom:has(video),
.bubble-me-custom:has(video) {
