    padding: 0 !important;
    margin: 0 !important;
}
.bubble-them-custom:has(img)::before, .bubble-me-custom:has(img)::before,
.bubble-them-custom:has(.msg-image-wrapper)::before, .bubble-me-custom:has(.msg-image-wrapper)::before,
.bubble-them-custom:has(video)::before, .bubble-me-custom:has(video)::before,
.bubble-them-custom:has(.voice-msg)::before, .bubble-me-custom:has(.voice-msg)::before,
.bubble-them-custom:has([class*="card"])::before, .bubble-me-custom:has([class*="card"])::before,
.bubble-them-custom:has(.gift-ig-container)::before, .bubble-me-custom:has(.gift-ig-container)::before {
    display: none !important;
}

.msg-image-wrapper,
.msg-image-wrapper img {
    border-radius: 8px !important;
    max-width: 180px !important;
    max-height: 240px !important;
    display: block !important;
