 * ★ 我方 — 已领取（has check）
 * ================================================ */
/* 日间已领取图 */
.chat-detail-screen[data-time-of-day="morning"] .bubble-me-custom .msg-transfer-card:has(.msg-transfer-check)::before,
.chat-detail-screen[data-time-of-day="day"] .bubble-me-custom .msg-transfer-card:has(.msg-transfer-check)::before {
