[data-color-scheme="dark"] .nj-moments-header-sticky {
    background: rgba(17, 17, 17, 0.85) !important;
    backdrop-filter: blur(20px) !important;
    -webkit-backdrop-filter: blur(20px) !important;
}

/* ==========================================
   修复底栏毛玻璃透色 (日夜双模式，安全高度版)
========================================== */
/* 夜间模式：聊天、主页、收藏用深灰底板，高度450避开搜索栏 */
[data-color-scheme="dark"] #messaging-chat-tab::after,
[data-color-scheme="dark"] #messaging-profile-tab::after,
[data-color-scheme="dark"] #messaging-favorites-tab::after {
    content: '' !important;
    position: fixed !important;
    left: 0 !important; right: 0 !important; bottom: 0 !important;
    height: 450px !important; 
    background-color: #171717 !important;
    z-index: -1 !important;
    pointer-events: none !important;
}

/* 朋友圈专属底板：颜色改纯黑，高度直接拉满全屏！ */
[data-color-scheme="dark"] #messaging-moments-tab::after {
    content: '' !important;
    position: fixed !important;
    left: 0 !important; right: 0 !important; bottom: 0 !important;
    height: 75vh !important; /* 100vh就是填满整个屏幕的高度 */
    background-color: #1a1a1a !important; /* 和朋友圈背景融为一体 */
    z-index: -1 !important;
    pointer-events: none !important;
}

/* 白天模式：纯白底板 */
[data-color-scheme="light"] #messaging-chat-tab::after,
[data-color-scheme="light"] #messaging-moments-tab::after,
[data-color-scheme="light"] #messaging-profile-tab::after,
[data-color-scheme="light"] #messaging-favorites-tab::after {
    content: '' !important;
    position: fixed !important;
    left: 0 !important; right: 0 !important; bottom: 0 !important;
    height: 750px !important;
    background-color: #ffffff !important;
    z-index: -1 !important;
    pointer-events: none !important;
}

.nj-chat-tab-search-wrap {
    background-color: #ededed !important;
}
[data-color-scheme="dark"] .nj-chat-tab-search-wrap {
    background-color: #111111 !important;
}

/* 修复切换账号按钮位置 */
.nj-chat-tab-header-title-btn {
    position: absolute !important;
    left: 50% !important;
    top: calc(17px + var(--nuo-safe-top)) !important;
    transform: translate(-50%, -50%) !important;
    width: 100px !important; 
    height: 40px !important;
    z-index: 110 !important;
}
